  hrRegOk: async t => { const [emp, date] = t.dataset.k.split('|'); const e = hrEmp(emp), P = HRM().attPolicy; const reason = (v('rg_reason') || '').trim(); if (!reason) return toast('Reason is required.', 'bad'); const f = document.getElementById('rg_proof'); if (!f || !f.files[0]) return toast('Proof is required.', 'bad'); if (HRT().attLocks[date.slice(0, 7)]) return toast('Month is locked – corrections after lock need HR and Payroll approval (HR control centre).', 'bad'); const n = HRT().regs.filter(r => r.emp === emp && r.date.slice(0, 7) === date.slice(0, 7) && r.status !== 'Rejected').length; if (n >= P.regLimit) return toast(`Maximum ${P.regLimit} regularisation requests per month reached.`, 'bad'); if (pcAddDays(date, P.regDays) < PROC_TODAY) return toast(`Regularisation allowed within ${P.regDays} days.`, 'bad'); const tx = Store.clone(HRT()); const r = { id: 'RG' + Date.now().toString(36), no: hrNo(tx, 'REG'), emp, date, was: hrAtt(e, date).status, want: v('rg_want'), in: v('rg_in'), out: v('rg_out'), reason, proof: f.files[0].name, status: 'Submitted', chain: hrChain('Regularisation', { bid: e.bid }), level: 0, createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), userMade: true, log: [] }; hrLog(r, 'Submitted', ''); tx.regs.unshift(r); await hrSave(tx); hrNotifyLevel(r, 'hr_att'); audit('HRMS', 'Attendance regularisation requested', { new: `${r.no} · ${emp} · ${date} · ${r.was} → ${r.want}` }); closeModal(); toast(`${r.no} submitted – awaiting ${hrAwaiting(r)}.`); },
