  hrAttImport: t => { const f = t.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = async () => { try { const wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' }), raw = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '', raw: false }); const norm = h => String(h).toLowerCase().replace(/[^a-z]/g, ''); const col = (o, ks) => { const k = Object.keys(o).find(h => ks.includes(norm(h))); return k ? o[k] : ''; }; const tx = Store.clone(HRT()); let ok = 0, bad = 0, locked = 0; raw.forEach(o => { const id = String(col(o, ['employeeid', 'empid', 'biometricid', 'id'])).trim(), d = rmParseDate(col(o, ['date', 'attendancedate'])), tin = String(col(o, ['in', 'intime', 'punchin'])).trim(), tout = String(col(o, ['out', 'outtime', 'punchout'])).trim(); const e = hrEmp(id) || hrEmps().find(x => x.bio === id); if (!e || !d) { bad++; return; } if (tx.attLocks[d.slice(0, 7)]) { locked++; return; } tx.attOverrides[e.id + '|' + d] = { status: tin && tout ? 'Present' : tin || tout ? 'Single punch' : 'Absent', src: 'Import', in: tin, out: tout, reason: 'Imported ' + f.name, by: App.user.name, at: nowIso() }; ok++; }); tx.attImports.unshift({ id: 'AI' + Date.now().toString(36), at: nowIso(), date: PROC_TODAY, by: App.user.name, devices: 0, punches: ok, failed: bad, status: `Imported (${f.name})${locked ? ' · ' + locked + ' rows skipped – locked month' : ''}` }); await hrSave(tx); audit('HRMS', 'Attendance imported', { new: `${f.name} · ${ok} rows · ${bad} rejected · ${locked} locked` }); toast(`${ok} punches imported, ${bad} rejected${locked ? ', ' + locked + ' in locked months skipped' : ''}.`); } catch (e) { toast('Import failed: ' + e.message, 'bad'); } }; rd.readAsArrayBuffer(f); t.value = ''; },
